    col_tiles = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    source = None
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles):
            cells = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if any(v != bg for row in cells for v in row):
                source = cells
                break
        if source is not None:
